assert phone_token, 'phone_token missing'

def fetch_all_contacts(relationship):
    all_contacts = []
    page_index = 0
    page_limit = 20
    while True:
        resp = apis.phone.search_contacts(access_token=phone_token, relationship=relationship, page_index=page_index, page_limit=page_limit)
